solution.code:
const message = await document.querySelector("#message");
const changeButton = await document.querySelector("#change-text");
changeButton.addEventListener("click", () => {
  message.textContent = "تم تغيير النص!";
});

const list = await document.querySelector("#items");
const addButton = await document.querySelector("#add-item");
addButton.addEventListener("click", () => {
  const item = document.createElement("li");
  item.textContent = "عنصر جديد";
  list.appendChild(item);
});
console.log("جرّب أزرار المعاينة.");
